    return Decimal(x).quantize(Q, rounding=ROUND_HALF_UP)


def tier_rate(customer):
    return {'gold': Decimal('0.05'), 'silver': Decimal('0.02')}.get(customer.get('tier'), Decimal('0'))


def tax_rate(customer):
